begin;
set local lock_timeout='5s';set local statement_timeout='90s';
create table public.stay_service_applications(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.places_properties(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,request_id uuid not null,model text not null check(model in('BOOKING_PARTNER','STAY_MANAGEMENT','FULLY_MANAGED')),message text not null check(length(btrim(message)) between 10 and 2000),status text not null default 'NEW' check(status in('NEW','IN_REVIEW','CONTACTED','CLOSED','WITHDRAWN')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,request_id));
create index stay_app_property_idx on public.stay_service_applications(property_id,created_at desc);create index stay_app_status_idx on public.stay_service_applications(status,created_at desc);
create table public.stay_service_agreements(
 id uuid primary key,stay_property_id uuid not null references public.stay_properties(id) on delete restrict,places_property_id uuid references public.places_properties(id) on delete restrict,
 model text not null check(model in('BOOKING_PARTNER','STAY_MANAGEMENT','FULLY_MANAGED')),status text not null default 'DRAFT' check(status in('DRAFT','ACTIVE','SUSPENDED','ENDED')),
 scope text not null default '',responsibilities text not null default '',contract_reference text not null default '',starts_at timestamptz,ends_at timestamptz,
 fee_type text not null check(fee_type in('NONE','COMMISSION','PMS_SUBSCRIPTION','MANAGEMENT_FEE')),fee_amount_idr bigint check(fee_amount_idr between 0 and 999999999999),fee_bps integer check(fee_bps between 0 and 9999),
 billing_basis text not null check(billing_basis in('NONE','EMBEDDED_BOOKING_MARGIN','MANUAL_CONTRACT_TRACKING')),payment_route text not null check(payment_route in('EXISTING_SHIAP_BANK_TRANSFER','DIRECT_TO_PROPERTY_PLANNED')),
 settlement_party text not null check(settlement_party in('SHIAP','PROPERTY')),account_manager_id uuid references public.admin_users(user_id) on delete restrict,
 version integer not null default 1,last_request_id uuid not null unique,last_payload jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),updated_by uuid not null references auth.users(id) on delete restrict,
 check(ends_at is null or starts_at is not null and ends_at>starts_at),check(fee_amount_idr is null or fee_bps is null),check(status<>'ACTIVE' or model='BOOKING_PARTNER' and payment_route='EXISTING_SHIAP_BANK_TRANSFER' and settlement_party='SHIAP' and billing_basis in('NONE','EMBEDDED_BOOKING_MARGIN') and starts_at is not null and ends_at is not null and length(btrim(contract_reference))>=5 and length(btrim(scope))>=10 and length(btrim(responsibilities))>=10 and account_manager_id is not null)
);
create unique index stay_one_active_agreement on public.stay_service_agreements(stay_property_id) where status='ACTIVE';create index stay_agreements_places_idx on public.stay_service_agreements(places_property_id);create index stay_agreements_manager_idx on public.stay_service_agreements(account_manager_id);
create table public.stay_agreement_members(agreement_id uuid not null references public.stay_service_agreements(id) on delete restrict,user_id uuid not null references auth.users(id) on delete restrict,role text not null check(role in('OWNER','FRONTDESK','FINANCE')),status text not null check(status in('ACTIVE','REVOKED')),verified_by uuid not null references public.admin_users(user_id) on delete restrict,verified_at timestamptz not null default now(),primary key(agreement_id,user_id));
create index stay_agreement_members_user_idx on public.stay_agreement_members(user_id,status);
alter table public.stay_service_applications enable row level security;alter table public.stay_service_agreements enable row level security;alter table public.stay_agreement_members enable row level security;
revoke all on public.stay_service_applications,public.stay_service_agreements,public.stay_agreement_members from public,anon,authenticated;
grant select on public.stay_service_applications to authenticated;
grant select(id,stay_property_id,places_property_id,model,status,scope,responsibilities,contract_reference,starts_at,ends_at,fee_type,fee_amount_idr,fee_bps,billing_basis,payment_route,settlement_party,account_manager_id,version,created_at,updated_at) on public.stay_service_agreements to authenticated;
grant select(agreement_id,user_id,role,status,verified_at) on public.stay_agreement_members to authenticated;
grant all on public.stay_service_applications,public.stay_service_agreements,public.stay_agreement_members to service_role;
create function shiap_private.stay_agreement_member(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.stay_agreement_members where agreement_id=p_id and user_id=auth.uid() and status='ACTIVE')$$;
revoke all on function shiap_private.stay_agreement_member(uuid) from public,anon;grant execute on function shiap_private.stay_agreement_member(uuid) to authenticated,service_role;
create policy stay_app_own on public.stay_service_applications for select to authenticated using(public.is_shiap_admin() or user_id=auth.uid());
create policy stay_agreement_read on public.stay_service_agreements for select to authenticated using(public.is_shiap_admin() or shiap_private.stay_agreement_member(id));
create policy stay_agreement_member_read on public.stay_agreement_members for select to authenticated using(public.is_shiap_admin() or user_id=auth.uid());
create function public.partner_request_stay_service(p_property_id uuid,p_model text,p_message text,p_request_id uuid) returns uuid language plpgsql security definer set search_path='' as $$declare old public.stay_service_applications%rowtype;result uuid;begin
 if auth.uid() is null or not shiap_private.places_billing_owner(p_property_id) or not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then raise exception 'Owner terverifikasi diperlukan.' using errcode='42501';end if;
 if p_model is null or p_model not in('BOOKING_PARTNER','STAY_MANAGEMENT','FULLY_MANAGED') or p_message is null or length(btrim(p_message)) not between 10 and 2000 or p_request_id is null then raise exception 'Permintaan tidak valid.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,8117));select * into old from public.stay_service_applications where user_id=auth.uid() and request_id=p_request_id;
 if found then if old.property_id<>p_property_id or old.model<>p_model or old.message<>btrim(p_message) then raise exception 'Request berubah.' using errcode='PT409';end if;return old.id;end if;
 if (select count(*) from public.stay_service_applications where user_id=auth.uid() and created_at>now()-interval '1 day')>=5 then raise exception 'Batas pengajuan harian tercapai.' using errcode='22023';end if;
 insert into public.stay_service_applications(property_id,user_id,request_id,model,message) values(p_property_id,auth.uid(),p_request_id,p_model,btrim(p_message)) returning id into result;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(p_property_id,auth.uid(),'STAY_SERVICE_REQUESTED',jsonb_build_object('id',result,'model',p_model));return result;end$$;
create function public.admin_review_stay_application(p_id uuid,p_status text,p_note text) returns void language plpgsql security definer set search_path='' as $$declare prop uuid;begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required' using errcode='42501';end if;
 if p_status is null or p_status not in('IN_REVIEW','CONTACTED','CLOSED') or p_note is null or length(btrim(p_note)) not between 10 and 2000 then raise exception 'Keputusan dan catatan wajib.' using errcode='22023';end if;
 update public.stay_service_applications set status=p_status,updated_at=now() where id=p_id and status<>'WITHDRAWN' returning property_id into prop;if not found then raise exception 'Pengajuan tidak tersedia.' using errcode='P0002';end if;
 insert into public.places_partner_audit_logs(property_id,actor_id,event,new_state) values(prop,auth.uid(),'STAY_APPLICATION_REVIEW',jsonb_build_object('id',p_id,'status',p_status,'note',btrim(p_note)));end$$;
create function public.admin_save_stay_agreement(p_id uuid,p_version integer,p_request_id uuid,p_terms jsonb) returns integer language plpgsql security definer set search_path='' as $$
declare old public.stay_service_agreements%rowtype;stay_id uuid;places_id uuid;manager uuid;v integer;begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required' using errcode='42501';end if;
 if p_id is null or p_request_id is null or p_version is null or p_version<0 or p_terms is null or jsonb_typeof(p_terms)<>'object' or exists(select 1 from jsonb_object_keys(p_terms)k where k not in('stay_property_id','places_property_id','model','status','scope','responsibilities','contract_reference','starts_at','ends_at','fee_type','fee_amount_idr','fee_bps','billing_basis','payment_route','settlement_party','account_manager_id')) then raise exception 'Data perjanjian tidak valid.' using errcode='22023';end if;
 if length(coalesce(p_terms->>'scope',''))>5000 or length(coalesce(p_terms->>'responsibilities',''))>5000 or length(coalesce(p_terms->>'contract_reference',''))>500 then raise exception 'Isi perjanjian terlalu panjang.' using errcode='22023';end if;
 stay_id:=(p_terms->>'stay_property_id')::uuid;places_id:=nullif(p_terms->>'places_property_id','')::uuid;manager:=nullif(p_terms->>'account_manager_id','')::uuid;
 perform 1 from public.stay_properties where id=stay_id for update;if not found then raise exception 'Properti Stay diperlukan.' using errcode='22023';end if;
 select * into old from public.stay_service_agreements where id=p_id for update;
 if found then if old.last_request_id=p_request_id then if old.last_payload<>p_terms then raise exception 'Request berubah.' using errcode='PT409';end if;return old.version;end if;if old.version<>p_version or old.stay_property_id<>stay_id then raise exception 'Perjanjian berubah atau properti tidak sama.' using errcode='PT409';end if;
 elsif p_version<>0 then raise exception 'Perjanjian berubah.' using errcode='PT409';end if;
 if places_id is not null and not exists(select 1 from public.places_properties where id=places_id and stay_property_id=stay_id and stay_mapping_verified_at is not null) then raise exception 'Pemetaan Places–Stay harus diverifikasi secara terpisah.' using errcode='22023';end if;
 if p_terms->>'status'='ACTIVE' and (p_terms->>'model'<>'BOOKING_PARTNER' or p_terms->>'payment_route'<>'EXISTING_SHIAP_BANK_TRANSFER' or p_terms->>'settlement_party'<>'SHIAP' or p_terms->>'billing_basis' not in('NONE','EMBEDDED_BOOKING_MARGIN')) then raise exception 'PMS mandiri, pembayaran langsung dan operasi lapangan belum siap untuk aktivasi. Simpan draft saja.' using errcode='22023';end if;
 if p_terms->>'status'='ACTIVE' and (not exists(select 1 from public.stay_properties where id=stay_id and status='published') or not exists(select 1 from public.stay_room_types where property_id=stay_id and status='active') or not exists(select 1 from public.payment_settings where id and is_active and length(btrim(account_number))>0 and length(btrim(account_name))>0)) then raise exception 'Katalog, inventori dan pembayaran Stay yang ada harus siap.' using errcode='22023';end if;
 if (p_terms->>'fee_type'='NONE' and (coalesce((p_terms->>'fee_amount_idr')::bigint,0)<>0 or coalesce((p_terms->>'fee_bps')::integer,0)<>0)) or (p_terms->>'fee_type'='COMMISSION' and p_terms->>'fee_bps' is null) or (p_terms->>'fee_type' in('PMS_SUBSCRIPTION','MANAGEMENT_FEE') and p_terms->>'fee_amount_idr' is null) then raise exception 'Satu jenis biaya harus sesuai kontrak; tidak ada fee otomatis.' using errcode='22023';end if;
 v:=coalesce(old.version,0)+1;
 insert into public.stay_service_agreements(id,stay_property_id,places_property_id,model,status,scope,responsibilities,contract_reference,starts_at,ends_at,fee_type,fee_amount_idr,fee_bps,billing_basis,payment_route,settlement_party,account_manager_id,version,last_request_id,last_payload,updated_by)
 values(p_id,stay_id,places_id,p_terms->>'model',p_terms->>'status',coalesce(p_terms->>'scope',''),coalesce(p_terms->>'responsibilities',''),coalesce(p_terms->>'contract_reference',''),nullif(p_terms->>'starts_at','')::timestamptz,nullif(p_terms->>'ends_at','')::timestamptz,p_terms->>'fee_type',nullif(p_terms->>'fee_amount_idr','')::bigint,nullif(p_terms->>'fee_bps','')::integer,p_terms->>'billing_basis',p_terms->>'payment_route',p_terms->>'settlement_party',manager,v,p_request_id,p_terms,auth.uid())
 on conflict(id) do update set places_property_id=excluded.places_property_id,model=excluded.model,status=excluded.status,scope=excluded.scope,responsibilities=excluded.responsibilities,contract_reference=excluded.contract_reference,starts_at=excluded.starts_at,ends_at=excluded.ends_at,fee_type=excluded.fee_type,fee_amount_idr=excluded.fee_amount_idr,fee_bps=excluded.fee_bps,billing_basis=excluded.billing_basis,payment_route=excluded.payment_route,settlement_party=excluded.settlement_party,account_manager_id=excluded.account_manager_id,version=v,last_request_id=p_request_id,last_payload=p_terms,updated_by=auth.uid(),updated_at=now();
 insert into public.places_partner_audit_logs(property_id,actor_id,event,old_state,new_state) values(places_id,auth.uid(),'STAY_AGREEMENT_SAVED',case when old.id is null then null else jsonb_build_object('id',old.id,'status',old.status,'version',old.version) end,jsonb_build_object('id',p_id,'status',p_terms->>'status','version',v,'automatic_charge',false));return v;end$$;
alter table public.stay_service_agreements add constraint stay_fee_model_consistent check(case model when 'BOOKING_PARTNER' then fee_type in('NONE','COMMISSION') when 'STAY_MANAGEMENT' then fee_type in('NONE','PMS_SUBSCRIPTION') else fee_type in('NONE','COMMISSION','MANAGEMENT_FEE') end);
create function public.admin_set_stay_agreement_member(p_id uuid,p_user_id uuid,p_role text,p_active boolean,p_confirm boolean,p_note text) returns void language plpgsql security definer set search_path='' as $$declare agreement public.stay_service_agreements%rowtype;begin
 if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required.' using errcode='42501';end if;
 if p_user_id is null or p_role is null or p_role not in('OWNER','FRONTDESK','FINANCE') or p_active is null or p_note is null or length(btrim(p_note)) not between 10 and 2000 then raise exception 'Peran dan catatan diperlukan.' using errcode='22023';end if;
 select * into agreement from public.stay_service_agreements where id=p_id for update;if not found then raise exception 'Perjanjian tidak tersedia.' using errcode='P0002';end if;
 if p_active and (p_confirm is distinct from true or not exists(select 1 from auth.users where id=p_user_id and email_confirmed_at is not null) or agreement.status<>'ACTIVE') then raise exception 'Perjanjian aktif dan verifikasi kewenangan nyata diperlukan.' using errcode='22023';end if;
 insert into public.stay_agreement_members(agreement_id,user_id,role,status,verified_by) values(p_id,p_user_id,p_role,case when p_active then 'ACTIVE' else 'REVOKED' end,auth.uid()) on conflict(agreement_id,user_id) do update set role=excluded.role,status=excluded.status,verified_by=auth.uid(),verified_at=now();
 insert into public.places_partner_audit_logs(property_id,actor_id,subject_user_id,event,new_state) values(agreement.places_property_id,auth.uid(),p_user_id,'STAY_ACCESS_DECISION',jsonb_build_object('agreement_id',p_id,'role',p_role,'active',p_active,'note',btrim(p_note)));end$$;
create function public.partner_stay_snapshot(p_id uuid,p_day date default (now() at time zone 'Asia/Makassar')::date) returns jsonb language plpgsql stable security definer set search_path='' as $$declare a public.stay_service_agreements%rowtype;rooms jsonb;metrics jsonb;begin
 if auth.uid() is null or not(public.is_shiap_admin() or shiap_private.stay_agreement_member(p_id)) then raise exception 'Akses perjanjian diperlukan.' using errcode='42501';end if;
 select * into a from public.stay_service_agreements where id=p_id and status='ACTIVE' and starts_at<=now() and ends_at>now();if not found then raise exception 'Perjanjian belum aktif atau sudah berakhir.' using errcode='22023';end if;
 if p_day is null or p_day<(now() at time zone 'Asia/Makassar')::date-365 or p_day>(now() at time zone 'Asia/Makassar')::date+365 then raise exception 'Tanggal di luar rentang.' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'capacity',capacity,'total_units',total_units)),'[]') into rooms from public.stay_room_types where property_id=a.stay_property_id and status='active';
 select jsonb_build_object('paid_reservation_items',count(*),'scheduled_check_ins',count(*) filter(where i.date_start=p_day),'scheduled_check_outs',count(*) filter(where i.date_end=p_day),'paid_units_tonight',coalesce(sum(i.quantity) filter(where i.date_start<=p_day and i.date_end>p_day),0)) into metrics from public.booking_items i join public.booking_orders b on b.id=i.booking_id where i.property_id=a.stay_property_id and i.service_type='stay' and b.payment_status='paid' and b.order_status in('confirmed','completed') and i.date_start<=p_day and i.date_end>=p_day;
 return jsonb_build_object('day',p_day,'rooms',rooms,'metrics',metrics,'availability_is_not_inferred',true,'settlement_automated',false,'payment_route',a.payment_route,'settlement_party',a.settlement_party);end$$;
revoke all on function public.partner_request_stay_service(uuid,text,text,uuid),public.admin_review_stay_application(uuid,text,text),public.admin_save_stay_agreement(uuid,integer,uuid,jsonb),public.admin_set_stay_agreement_member(uuid,uuid,text,boolean,boolean,text),public.partner_stay_snapshot(uuid,date) from public,anon;
grant execute on function public.partner_request_stay_service(uuid,text,text,uuid),public.admin_review_stay_application(uuid,text,text),public.admin_save_stay_agreement(uuid,integer,uuid,jsonb),public.admin_set_stay_agreement_member(uuid,uuid,text,boolean,boolean,text),public.partner_stay_snapshot(uuid,date) to authenticated;
commit;
